import{_ as t,H as E,f as i,i as a}from"./chunks/framework.BH2BK_3i.js";const p=JSON.parse('{"title":"代码评点01 | 不同语言TDD的节奏有何不同？","description":"","frontmatter":{},"headers":[{"level":2,"title":"代码评点","slug":"代码评点","link":"#代码评点","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·TDD项目实战70讲/代码评点01｜不同语言TDD的节奏有何不同？.md","filePath":"徐昊·TDD项目实战70讲/代码评点01｜不同语言TDD的节奏有何不同？.md","lastUpdated":1795563222000}'),s={name:"徐昊·TDD项目实战70讲/代码评点01｜不同语言TDD的节奏有何不同？.md"};function n(r,e,A,B,o,l){return E(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="代码评点01-不同语言tdd的节奏有何不同" tabindex="-1">代码评点01 | 不同语言TDD的节奏有何不同？ <a class="header-anchor" href="#代码评点01-不同语言tdd的节奏有何不同" aria-label="Permalink to &quot;代码评点01 | 不同语言TDD的节奏有何不同？&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B901/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B901/1.png" alt=""></a></p><ul><li><p>半了，截至目前，已有一千余人正式加入了学习。对于这个容量大、周期长的课程，相比销量和学习人数这两个数字，其实我们更关心和在意的是有多少同学可以坚持跟完，甚至学会。</p></li><li><p>基于此，徐老师特发起了“代码评点”的活动。不仅想让你跟上课程的发布节奏，同时也想给予一些针对性的反馈，帮助你更加平滑地过渡到下个实战项目中。活动详情，我们在之前每节课的结束部分都有预告。</p></li><li><p>此次提交作业的同学共有十余位，均已学完前 10 节课。徐老师仔细阅读后，将评点的详细内容总结成了文字与视频，如文稿中所示，供你学习与参考。</p></li></ul><p>你好，我是徐昊。到目前为止，我们用 11 节课展示了一个测试驱动开发的例子，并围绕这个例子讲解了测试驱动的核心概念与要点。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B901/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B901/2.png" alt=""></a></p><h2 id="代码评点" tabindex="-1">代码评点 <a class="header-anchor" href="#代码评点" aria-label="Permalink to &quot;代码评点&quot;">​</a></h2><p>今日，我们如约来到代码和作业点评的环节。颇为意外的是，在我们收到的作业中，有相当数量的同学尝试使用其他语言和 IDE，来重现 Args 的 TDD 流程。</p><p>这固然是很好的学习方法。不过有两点需要注意：一是不同的语言中，TDD 的节奏有很大不同；二是重构工具的支持不同。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B901/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B901/3.jpeg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B901/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B901/4.jpeg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B901/5.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/%25E4%25BB%25A3%25E7%25A0%2581%25E8%25AF%2584%25E7%2582%25B901/5.jpeg" alt=""></a></p><p>到这里，我们展示了在 Higher-order function 组合的函数风格下，进行 TDD 的节奏。那么下节课，我们来看看该怎么重构。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>我们的测试是行为验证还是状态验证？欢迎把你的思考和想法分享在留言区，我们下节课再见！</p>',14)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
